/// <summary>
/// The Permission namespace.
/// </summary>
namespace Fanex.Tarus.Security.Permission
{
    using Fanex.Tarus.Security.Criteria;
    using Fanex.Tarus.Security.Services.Implement;
    using Fanex.Tarus.Security.Services.Interface;

    /// <summary>
    /// Class SmartPunterPermissionService.
    /// </summary>
    public class SmartPunterPermissionService : ISmartPunterPermissionService
    {
        private ICheckSmartPunterService _smartPunterService;

        private string _smartPunterFunctionName = "SmartPunter";

        public SmartPunterPermissionService()
            : this(null)
        {
        }

        public SmartPunterPermissionService(ICheckSmartPunterService smartPunterService)
        {
            _smartPunterService = smartPunterService ?? new CheckSmartPunterService();
        }

        /// <summary>
        /// Check punter is smart or not.
        /// </summary>
        /// <param name="custID">Customer identify.</param>
        /// <returns><c>true</c> if XXXX, <c>false</c> otherwise.</returns>
        public bool IsDeniedViewSmartPunter(int? custID, string userName)
        {
            if (PermissionService.HasPermission(this._smartPunterFunctionName))
            {
                return false;
            }
            else
            {
                bool isSmartPunter = _smartPunterService.CheckSmartPunter(new CheckSmartPunterCriteria
                   {
                       CustID = custID.HasValue ? custID : null,
                       UserName = userName
                   });

                return isSmartPunter;
            }
        }
    }
}